function collides(lat,lon,radius=.34){const p=nAt(lat,lon).multiplyScalar(R);for(const b of buildings){if(p.distanceToSquared(b.center)>190)continue;const d=p.clone().sub(b.center);if(Math.abs(d.dot(b.e))<b.w*.5+radius&&Math.abs(d.dot(b.f))<b.d*.5+radius)return b;}return null;}
function moveWithCollision(a,heading,meters,radius=.35){if(Math.abs(meters)<.00001)return 0;const next=movePoint(a,heading,meters);if(!collides(next.lat,next.lon,radius)){a.lat=next.lat;a.lon=next.lon;return Math.abs(meters);}if(!collides(next.lat,a.lon,radius)){const d=Math.abs(next.lat-a.lat)*R;a.lat=next.lat;return d;}if(!collides(a.lat,next.lon,radius)){const d=Math.abs(wrap(next.lon-a.lon))*R*Math.cos(a.lat);a.lon=next.lon;return d;}return 0;}
