function audio(type){if(!soundOn||!audioCtx)return;try{audioCtx.resume();const t=audioCtx.currentTime,g=audioCtx.createGain();g.connect(audioCtx.destination);const o=audioCtx.createOscillator();o.connect(g);if(type==='shot'||type==='smg'){let len=.09,b=audioCtx.createBuffer(1,Math.floor(audioCtx.sampleRate*len),audioCtx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,3);let noise=audioCtx.createBufferSource();noise.buffer=b;let f=audioCtx.createBiquadFilter();f.type='lowpass';f.frequency.value=1800;noise.connect(f);f.connect(g);g.gain.setValueAtTime(type==='smg'?.035:.07,t);noise.start();return;}let freq={switch:440,melee:110,jump:240,crash:65,reward:660}[type]||280;o.type=type==='crash'?'triangle':'sine';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(type==='reward'?990:freq*.55,t+.13);g.gain.setValueAtTime(.035,t);g.gain.exponentialRampToValueAtTime(.001,t+.17);o.start();o.stop(t+.18);}catch(e){}}
