function updateCars(dt){for(const c of cars){if(c.disabled>0){c.disabled-=dt;c.body.rotation.z=Math.sin(worldTime*5)*.015;c.driver.visible=false;if(c.disabled<=0){c.health=100;c.body.rotation.z=0;c.driver.visible=c.occupied;}place(c.root,c.lat,c.lon,c.heading,.06);continue;}
 if(!c.player){if(c.police&&wanted>=.8){const d=distance(c,player);const desired=headingTo(c,player);c.heading=angleLerp(c.heading,desired,dt*1.6);const speed=d>6?Math.min(12,5+wanted*2):d>2.8?4:0;c.speed=lerp(c.speed,speed,dt*2);let moved=moveWithCollision(c,c.heading,c.speed*dt,.95);if(moved<.001&&d>8)c.heading+=dt*2;if(d<2.9&&heatAge%3<dt){hurt(activeCar?2:6);audio('crash');}if(d>64&&heatAge>10){const p=movePoint(player,player.heading+Math.PI,28);if(!collides(p.lat,p.lon,1)){c.lat=p.lat;c.lon=p.lon;}}}
 else if(c.traffic){c.speed=Math.abs(c.cruise);c.heading=c.cruise>0?Math.PI/2:-Math.PI/2;const future=movePoint(c,c.heading,c.speed*dt);if(activeCar&&distance(future,activeCar)<4.5){c.speed=0;}else{c.lon=future.lon;}}
 else c.speed*=Math.exp(-dt*3);}
 place(c.root,c.lat,c.lon,c.heading,.06);c.body.rotation.x=lerp(c.body.rotation.x,c.player&&Math.abs(c.speed)>1?-.025:0,dt*4);for(const w of c.wheels)w.rotation.x+=c.speed*dt/.37;c.driver.visible=c.occupied;
 if(c.police){for(let j=0;j<c.beacon.length;j++)c.beacon[j].visible=wanted>.5?Math.floor(worldTime*7+j)%2===0:true;}
 if(c!==activeCar&&activeCar&&distance(c,activeCar)<2.25&&Math.abs(activeCar.speed)>4){const oldSpeed=activeCar.speed;activeCar.speed*=-.27;c.speed=0;c.health-=Math.abs(oldSpeed)*.8;audio('crash');sparks(nAt(c.lat,c.lon).multiplyScalar(R+1));if(c.police)addHeat(.4);}
 }}
function updatePeds(dt){for(const p of peds){if(p.down>0){p.down-=dt;p.body.rotation.z=lerp(p.body.rotation.z,Math.PI*.48,dt*8);p.body.position.y=.2;if(p.down<=0){p.body.rotation.z=0;p.body.position.y=0;p.panic=5;}continue;}let sp=p.panic>0?2.1:p.speed;p.panic=Math.max(0,p.panic-dt);if(activeCar&&distance(p,activeCar)<2&&Math.abs(activeCar.speed)>5){p.down=4;addHeat(.4);continue;}p.heading=p.panic>0?headingTo(player,p):Math.PI/2;moveWithCollision(p,p.heading,sp*dt,.3);place(p.root,p.lat,p.lon,p.heading,.06);animateHuman(p,dt,sp);if(p.panic>0){p.arms[0].rotation.z=-2.6;p.arms[1].rotation.z=2.6;}}
 for(const t of targets){t.hitTimer=Math.max(0,t.hitTimer-dt);t.face.rotation.z=Math.sin(worldTime*1.5)*.07;t.face.visible=t.hitTimer<=0;t.root.children[1].scale.y=1;}
}
function updateEffectsV4(dt){for(let i=fx.length-1;i>=0;i--){let f=fx[i];f.time-=dt;if(f.time<=0){scene.remove(f.root);if(f.type==='line')f.root.geometry.dispose();f.root.material.dispose();fx.splice(i,1);continue;}if(f.velocity)f.root.position.addScaledVector(f.velocity,dt);f.root.material.opacity=Math.min(1,f.time/f.max);if(f.type==='spark')f.root.scale.multiplyScalar(Math.exp(-dt*4));}}
