 if(!activeCar)findNearestCar();const context=$('context');if(!orbit&&(activeCar||nearestCar)&&started){context.style.display='block';setText('contextText',activeCar?'下车':nearestCar.occupied?'抢这辆车':'驾驶这辆车');}else context.style.display='none';
