function drawRadar(){const c=$('radar'),g=c.getContext('2d'),W=c.width,mid=W/2,scale=4.0;g.clearRect(0,0,W,W);g.save();g.beginPath();g.arc(mid,mid,mid-2,0,TAU);g.clip();g.fillStyle='#183a36';g.fillRect(0,0,W,W);const a=frame(player.lat,player.lon,viewYaw),origin=nAt(player.lat,player.lon).multiplyScalar(R);function xy(lat,lon){const p=nAt(lat,lon).multiplyScalar(R).sub(origin);return [mid+p.dot(a.r)*scale,mid-p.dot(a.f)*scale];}g.lineCap='round';g.strokeStyle='#7d9a85';g.lineWidth=17;for(const lat of [-.58,0,.58]){g.beginPath();for(let i=0;i<=120;i++){const lon=i*TAU/120,p=xy(lat,lon);if(nAt(lat,lon).dot(nAt(player.lat,player.lon))<.65){g.moveTo(...p);continue;}if(i===0)g.moveTo(...p);else g.lineTo(...p);}g.stroke();}for(let i=0;i<4;i++){g.beginPath();for(let j=0;j<80;j++){let lat=-1.1+j*2.2/79,lon=i*Math.PI/2,p=xy(lat,lon);if(nAt(lat,lon).dot(nAt(player.lat,player.lon))<.45){g.moveTo(...p);continue;}j?g.lineTo(...p):g.moveTo(...p);}g.stroke();}g.fillStyle='#476c55';for(const b of buildings){if(distance(player,b)>42)continue;let p=xy(b.lat,b.lon);g.fillRect(p[0]-8,p[1]-8,16,16);}for(const t of targets){if(distance(player,t)>40)continue;let p=xy(t.lat,t.lon);g.fillStyle=t.hitTimer>0?'#547d6a':'#b4f5c5';g.beginPath();g.arc(...p,4,0,TAU);g.fill();}for(const c of cars){if(distance(player,c)>40)continue;let p=xy(c.lat,c.lon);g.fillStyle=c.police&&wanted>.5?'#ef9a8d':c===activeCar?'#f5ecc1':'#c5c9aa';g.fillRect(p[0]-3,p[1]-4,6,8);}g.save();g.translate(mid,mid);g.rotate(wrap(player.heading-viewYaw));g.fillStyle='#f2f4da';g.strokeStyle='#163c31';g.lineWidth=2;g.beginPath();g.moveTo(0,-9);g.lineTo(6,7);g.lineTo(0,4);g.lineTo(-6,7);g.closePath();g.fill();g.stroke();g.restore();g.restore();g.fillStyle='#d0e9cc';g.font='17px system-ui';g.textAlign='center';g.fillText('N',mid,22);}
