 window.addEventListener('keydown',e=>{if([' ','Tab','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(e.key==='Escape'){menuOpen?closeMenu():openMenu('help');return;}if(!started||menuOpen)return;const k=e.key.toLowerCase();if(!keys.has(k)){if(k==='e')enterExit();if(k==='q')setWeapon(weapon+1);if(k==='r')reload();if(k==='t')resetPlayer();if(k==='v')toggleOrbit();if(k===' ')jump();if(k>='1'&&k<='8')setWeapon(Number(k)-1);}keys.add(k);});window.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(e.key===' ')input.brake=false;});window.addEventListener('blur',()=>{keys.clear();fireHeld=false;input.fire=false;input.brake=false;resetStick();});document.addEventListener('visibilitychange',()=>{lastTime=performance.now()/1000;if(document.hidden){keys.clear();fireHeld=false;input.fire=false;}});
 const canvas=$('world');canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(!started||menuOpen||orbit)return;canvas.setPointerCapture(e.pointerId);if(e.pointerType==='touch'||e.button===2){lookPointer=e.pointerId;lookLast=[e.clientX,e.clientY];}else if(e.button===0){fireHeld=true;attack();}});canvas.addEventListener('pointermove',e=>{if(e.pointerId===lookPointer&&lookLast){viewYaw=wrap(viewYaw-(e.clientX-lookLast[0])*.007);viewPitch=clamp(viewPitch+(e.clientY-lookLast[1])*.006,-.3,1.7);lookLast=[e.clientX,e.clientY];}});const pointerUp=e=>{if(e.pointerId===lookPointer){lookPointer=null;lookLast=null;}fireHeld=false;};canvas.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',pointerUp);
 const joy=$('joystick');function updateStick(e){const r=joy.getBoundingClientRect(),size=r.width;let dx=e.clientX-r.left-size/2,dy=e.clientY-r.top-size/2,dist=Math.hypot(dx,dy),max=size*.32;if(dist>max){dx=dx/dist*max;dy=dy/dist*max;}input.x=dx/max;input.y=-dy/max;$('stick').style.transform=`translate(${dx}px,${dy}px)`;}joy.addEventListener('pointerdown',e=>{if(joystickPointer!==null)return;e.preventDefault();joystickPointer=e.pointerId;joy.setPointerCapture(e.pointerId);updateStick(e);});joy.addEventListener('pointermove',e=>{if(joystickPointer===e.pointerId)updateStick(e);});for(const name of ['pointerup','pointercancel','lostpointercapture'])joy.addEventListener(name,e=>{if(joystickPointer===e.pointerId)resetStick();});
 $('touchEnter').onclick=enterExit;$('touchWeapon').onclick=()=>setWeapon(weapon+1);$('touchSprint').onclick=()=>{input.sprint=!input.sprint;$('touchSprint').classList.toggle('on',input.sprint);};$('touchJump').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);jump();});for(const name of ['pointerup','pointercancel','lostpointercapture'])$('touchJump').addEventListener(name,()=>input.brake=false);$('touchFire').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);if(activeCar){audio('switch');toast('嘀嘀！');return;}input.fire=true;attack();});for(const name of ['pointerup','pointercancel','lostpointercapture'])$('touchFire').addEventListener(name,()=>input.fire=false);
