function enterExitV4(){if(!started||menuOpen||wheelMode||orbit)return;if(activeHeli){const h=activeHeli;if(h.altitude-supportHeight(h)>1||Math.abs(h.vertical)>1){toast('先降落，再下直升机');return;}let p=null;for(const sign of [-1,1]){const q=movePoint(h,h.heading+sign*Math.PI/2,2.1);if(!capsuleContact(q,.39,false,0,true)){p=q;break;}}if(!p){toast('舱门外有障碍，换个降落位置');return;}h.occupied=false;activeHeli=null;player.root.visible=true;player.lat=p.lat;player.lon=p.lon;player.heading=h.heading;viewYaw=h.heading;place(player.root,p.lat,p.lon,player.heading,.08);toast('已下机');return;}
 if(activeCar){const c=activeCar;if(Math.abs(c.speed)>7){input.brake=true;toast('减速后再下车');setTimeout(()=>input.brake=false,500);return;}let exit=null;for(const angle of [-Math.PI/2,Math.PI/2,Math.PI])for(const d of [1.7,2.15,2.7]){const p=movePoint(c,c.heading+angle,d);if(!capsuleContact(p,.40,false,0,true,c)){exit=p;break;}if(exit)break;}if(!exit){toast('车门被挡住了，往前挪一点');return;}enterExitGround();player.lat=exit.lat;player.lon=exit.lon;repairActor(player,.37,true);place(player.root,player.lat,player.lon,player.heading,.08);return;}
 findNearestCar();if(nearestHeli&&(!nearestCar||distance(player,nearestHeli)<distance(player,nearestCar))){activeHeli=nearestHeli;activeHeli.occupied=true;player.root.visible=false;player.lat=activeHeli.lat;player.lon=activeHeli.lon;player.heading=activeHeli.heading;viewYaw=activeHeli.heading;stopNavigation();lockPed=null;toast('已登机 · 左摇杆平飞 · 右侧升 / 降 · 松手悬停');audio('switch');return;}enterExitGround();}
function updatePlayerV4(dt){if(activeHeli){const h=activeHeli;player.lat=h.lat;player.lon=h.lon;player.heading=h.heading;cooldown=Math.max(0,cooldown-dt);return;}const before={lat:player.lat,lon:player.lon};updateGroundPlayer(dt);if(!activeCar)footDistance+=distance(before,player);else totalDriveDistance+=distance(before,player);refreshDistrict();}
function updateCarsV4(dt){updateGroundCars(dt);for(const c of cars){c.gear=clamp(Math.floor(Math.abs(c.speed)/8)+1,1,5);if(c.passenger)c.passenger.visible=!!c.passengerAboard;}}
function updateHelis(dt){for(const h of heliFleet){h.impactCooldown=Math.max(0,h.impactCooldown-dt);h.root.visible=h===activeHeli||orbit||!started||distance(h,player)<80;h.power=lerp(h.power,h.occupied?1:0,1-Math.exp(-dt*(h.occupied?1.8:.55)));h.rotor.rotation.y+=dt*(3+h.power*40);h.tailRotor.rotation.x+=dt*(4+h.power*58);h.blur.visible=h.power>.5;if(h!==activeHeli)continue;let x=input.x+(keys.has('d')?1:0)-(keys.has('a')?1:0),y=input.y+(keys.has('w')?1:0)-(keys.has('s')?1:0);const f=frame(h.lat,h.lon,viewYaw),m=Math.max(1,Math.hypot(x,y)),desired=f.f.clone().multiplyScalar(y/m*25).addScaledVector(f.r,-x/m*25);h.velocity.lerp(desired,1-Math.exp(-dt*1.8));let lift=input.lift||0;if(h.altitude>R*.8&&lift>0)lift*=clamp((R-h.altitude)/(R*.2),0,1);const targetVertical=h.power>.70?lift*7:0;h.vertical=lerp(h.vertical,targetVertical,1-Math.exp(-dt*2.5));const floor=supportHeight(h);h.altitude=Math.max(floor,h.altitude+h.vertical*dt);h.landed=h.altitude<=floor+.08;if(h.landed&&h.vertical<0)h.vertical=0;if(h.landed&&lift<=0)h.velocity.set(0,0,0);const next=displaceWorld(h,h.velocity.clone().multiplyScalar(dt)),v=nAt(next.lat,next.lon).multiplyScalar(R);let hit=null;for(const b of nearbyColliders(v,3.1)){if(h.altitude+.3>=b.h)continue;const result=circleContact(v,b,2.7);if(result){hit=result;break;}}if(hit){h.velocity.multiplyScalar(.05);if(h.impactCooldown<=0){h.health-=6;h.impactCooldown=.7;impactStrength=.45;audio('crash');sparks(nAt(h.lat,h.lon).multiplyScalar(R+h.altitude+1),0xe4d6a4,4);}}else{const n0=nAt(h.lat,h.lon),n1=nAt(next.lat,next.lon);h.velocity.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(n0,n1));setSurfacePosition(h,next);}if(h.velocity.length()>1.8){const direction=Math.atan2(h.velocity.dot(eastAt(h.lon)),h.velocity.dot(northAt(h.lat,h.lon)));h.heading=angleLerp(h.heading,direction,dt*2.5);}h.body.rotation.x=lerp(h.body.rotation.x,clamp(y*.18,-.18,.18),dt*3);h.body.rotation.z=lerp(h.body.rotation.z,-x*.16,dt*3);place(h.root,h.lat,h.lon,h.heading,h.altitude+.10);player.lat=h.lat;player.lon=h.lon;player.heading=h.heading;if(h.health<=0){h.health=100;h.altitude=supportHeight(helipads[0]);h.lat=helipads[0].lat;h.lon=helipads[0].lon;h.velocity.set(0,0,0);h.vertical=0;toast('直升机检修后返回停机坪');}refreshDistrict();}}
function summonVehicleV4(type){if(activeCar||activeHeli){toast('先下车 / 下机再呼叫载具');return false;}if(type==='helicopter'){const p=findOpenSpot(player,5.2,7);if(!p){toast('附近空间不足，请走到开阔地');return false;}const h=makeHelicopter();Object.assign(h,{lat:p.lat,lon:p.lon,heading:player.heading});actorGroup.add(h.root);place(h.root,h.lat,h.lon,h.heading,.1);heliFleet.push(h);toast('直升机已到达 · 靠近舱门后登机');return true;}const s=nearStreet(player).sample;if(!s)return false;let p=streetPoint(s.street,s.index,-3.1),slot=0;while(cars.some(c=>distance(c,p)<5)&&slot<12){slot++;p=streetPoint(s.street,clamp(s.index+slot*4,0,s.street.points.length-1),-3.1);}if(carContact({lat:p.lat,lon:p.lon,heading:p.heading,len:4},p)){toast('路边位置被占用，请换一个位置');return false;}const c=addCar(p.lat,p.lon,p.heading,type==='taxi'?0xe1b64c:0xb64337,type==='taxi'?'taxi':'coupe');c.occupied=false;toast(type==='taxi'?'出租车已到路边，靠近后上车':'跑车已到路边，靠近后上车');return true;}
function updateAdvancedAudio(dt){if(!audioCtx||!soundOn)return;const now=audioCtx.currentTime;if(activeCar&&engineOsc){const speed=Math.abs(activeCar.speed),rev=speed-(activeCar.gear-1)*8;engineOsc.frequency.setTargetAtTime(58+Math.max(0,rev)*12+(input.y>0?15:0),now,.08);engineGain.gain.setTargetAtTime(.014+speed*.00035,now,.12);}if(!heliRotorOsc){heliRotorOsc=audioCtx.createOscillator();heliRotorGain=audioCtx.createGain();heliRotorOsc.type='sawtooth';heliRotorOsc.frequency.value=48;heliRotorGain.gain.value=0;heliRotorOsc.connect(heliRotorGain);heliRotorGain.connect(audioCtx.destination);heliRotorOsc.start();}heliRotorGain.gain.setTargetAtTime(activeHeli?.018*activeHeli.power:0,now,.20);heliRotorOsc.frequency.setTargetAtTime(37+(activeHeli?.power||0)*22,now,.2);}

// Three complete loops: hailing taxi fares, street time trials and helicopter deliveries.
let job=null,taxiRiders=[],jobMarker=null,gpsRoute=[],taxiTrips=0,raceWins=0,flightTrips=0,totalDriveDistance=0,jobMessage='',saveTimer=0;
function resetJobs(){job={type:'taxi',stage:'seek',completed:0,time:0,goal:null,passenger:null,boarding:0};taxiRiders=[];gpsRoute=[];jobMarker=null;missionStage=3;}
function roadRoute(start,goal){const a=nearStreet(start).sample,b=nearStreet(goal).sample;if(!a||!b)return [goal];const vertices=[{...start},{...goal}],members=streets.map(()=>[]);members[a.street.id].push({id:0,index:a.index});members[b.street.id].push({id:1,index:b.index});for(const j of junctions){const id=vertices.length;vertices.push({lat:j.lat,lon:j.lon});members[j.a].push({id,index:j.ia});members[j.b].push({id,index:j.ib});}const edges=vertices.map(()=>[]);for(const s of streets){if(s.pedestrian10&&(activeCar||job?.type==='taxi'||job?.type==='race'))continue;const nodes=members[s.id].sort((x,y)=>x.index-y.index);for(let i=0;i<nodes.length-1+(s.loop?1:0);i++){const A=nodes[i%nodes.length],B=nodes[(i+1)%nodes.length];if(!A||!B||A.id===B.id)continue;const delta=i===nodes.length-1?s.length-s.cumulative[A.index]+s.cumulative[B.index]:s.cumulative[B.index]-s.cumulative[A.index];edges[A.id].push({to:B.id,cost:Math.max(.1,delta),street:s,from:A.index,end:B.index,dir:1});edges[B.id].push({to:A.id,cost:Math.max(.1,delta),street:s,from:B.index,end:A.index,dir:-1});}}
 const best=vertices.map(()=>Infinity),previous=[],done=new Set();best[0]=0;for(let tries=0;tries<vertices.length;tries++){let u=-1;for(let i=0;i<vertices.length;i++)if(!done.has(i)&&(u<0||best[i]<best[u]))u=i;if(u<0||!Number.isFinite(best[u]))break;if(u===1)break;done.add(u);for(const e of edges[u])if(best[u]+e.cost<best[e.to]){best[e.to]=best[u]+e.cost;previous[e.to]={u,e};}}
 if(!previous[1])return [goal];const route=[];for(let u=1;u!==0;){const p=previous[u];if(!p)break;route.push(p.e);u=p.u;}route.reverse();const points=[];for(const e of route){const n=e.street.points.length-1;let idx=e.from,guard=0;while(idx!==e.end&&guard++<n+2){if(guard%4===1)points.push(e.street.points[idx]);idx=(idx+e.dir+n)%n;}points.push(e.street.points[e.end]);}points.push(goal);return points;}
function setJobGoal(p){job.goal=p?{lat:p.lat,lon:p.lon,height:p.height||0}:null;gpsRoute=p?roadRoute(player,p):[];if(p)showJobMarker(p);else if(jobMarker)jobMarker.visible=false;}
function showJobMarker(p){if(!jobMarker){jobMarker=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(1.05,.055,6,40),basic(0xf3d77b,{transparent:true,opacity:.85}));ring.rotation.x=Math.PI/2;jobMarker.add(ring);const arrow=new THREE.Mesh(new THREE.ConeGeometry(.28,.5,5),basic(0xf1dc8f));arrow.rotation.x=Math.PI;arrow.position.y=2.7;jobMarker.add(arrow);actorGroup.add(jobMarker);}place(jobMarker,p.lat,p.lon,0,(p.height||0)+.17);jobMarker.visible=true;}
function createJobActors(){for(let i=0;i<8;i++){const s=streets[i===0?5:1+i%8],idx=i===0?310:70+i*47,p0=streetPoint(s,idx,i%2?5.3:-5.3),r=makeCharacter((i*3+1)%12,true);Object.assign(r,{lat:p0.lat,lon:p0.lon,heading:p0.heading,speed:1.3,down:0,panic:0,hailing:true,taxiPassenger:true,passengerState:'waiting',road:s,roadIndex:idx,roadDir:1,side:i%2?5.3:-5.3,timer:0});repairActor(r,.28);actorGroup.add(r.root);place(r.root,r.lat,r.lon,r.heading,.08);const ring=new THREE.Mesh(new THREE.TorusGeometry(.44,.025,5,24),basic(0xf3d57c));ring.rotation.x=Math.PI/2;ring.position.y=.055;r.root.add(ring);r.hailRing=ring;taxiRiders.push(r);peds.push(r);}setJobGoal(taxiRiders[0]);}
function startJob(type){if(job?.passenger){toast('先完成当前乘客订单');return false;}if(jobMarker)jobMarker.visible=false;job={type,stage:type==='taxi'?'seek':type==='race'?'getcar':'board',time:0,completed:0,goal:null,passenger:null,boarding:0};if(type==='taxi'){const rider=taxiRiders.filter(r=>r.passengerState==='waiting'&&r.down<=0).sort((a,b)=>distance(player,a)-distance(player,b))[0];setJobGoal(rider||null);toast('出租车任务 · 开出租车靠近招手乘客，停稳即可接客');}else if(type==='race'){const a=nearStreet(player).sample,s=a.street;job.checkpoints=[];for(let i=0;i<6;i++){const idx=(a.index+18+i*23)%(s.points.length-1);job.checkpoints.push({...s.points[idx],height:0});}job.limit=100;setJobGoal(job.checkpoints[0]);toast('街头计时赛 · 任意汽车 · 100 秒通过 6 个检查点');}else{job.destination=helipads[1];setJobGoal(helipads[0]);toast('直升机投递 · 登机后飞往另一座停机坪并降落');}return true;}
function boardTaxi(rider,c){job.passenger=rider;job.stage='boarding';job.boarding=0;const A=movePoint(c,c.heading-Math.PI/2,1.40),B=movePoint(c,c.heading+Math.PI/2,1.40);rider.doorSign=distance(rider,A)<=distance(rider,B)?-1:1;rider.hailing=false;rider.hailRing.visible=false;rider.passengerState='boarding';c.speed=0;toast('乘客走向车门 · 请停稳');}
function finishTaxi(){const r=job.passenger,c=activeCar||job.taxi;if(!r||!c)return;const p=findTaxiExit(c);if(!p){toast('路边被挡住，请往前挪一点再停车');return;}r.inTaxi=false;r.passengerState='leaving';r.timer=12;r.lat=p.lat;r.lon=p.lon;r.heading=c.heading+Math.PI/2;r.root.visible=true;r.body.rotation.set(0,0,0);place(r.root,r.lat,r.lon,r.heading,.08);c.passengerAboard=false;const fare=job.fare+Math.round(Math.max(0,job.timeLimit-job.time)*.08);cash+=fare;taxiTrips++;jobMessage='送达 +$'+fare;toast('乘客已送达 · +$'+fare+' · 已完成 '+taxiTrips+' 单');audio('reward');job.passenger=null;job.stage='seek';job.time=0;const next=taxiRiders.filter(p=>p.passengerState==='waiting').sort((a,b)=>distance(player,a)-distance(player,b))[0];setJobGoal(next||null);saveProgress();}
