function updateJobs(dt){if(!job)return;for(const r of taxiRiders){if(r.down>0){r.hailing=false;r.down-=dt;r.body.rotation.z=lerp(r.body.rotation.z,1.45,dt*8);if(r.down<=0){r.body.rotation.z=0;r.panic=3;}continue;}if(r.inTaxi){r.root.visible=false;continue;}r.root.visible=orbit||distance(player,r)<65;if(r.passengerState==='waiting'){r.hailing=r.panic<=0;r.hailRing.visible=r.hailing;if(r.panic>0){r.panic-=dt;r.heading=headingTo(player,r);moveWithCollision(r,r.heading,dt*2.5,.28);}animateHuman(r,dt,r.panic>0?2.5:0);}else if(r.passengerState==='leaving'){r.timer-=dt;moveWithCollision(r,r.heading,dt*1.1,.28);animateHuman(r,dt,1.1);if(r.timer<=0){r.passengerState='waiting';r.hailing=true;r.hailRing.visible=true;}}place(r.root,r.lat,r.lon,r.heading,.08);}
 if(job.type==='taxi'){if(job.stage==='seek'){if(!job.goal){const r=taxiRiders.find(p=>p.passengerState==='waiting');if(r)setJobGoal(r);}if(activeCar?.type==='taxi'&&Math.abs(activeCar.speed)<.8){const r=taxiRiders.filter(p=>p.passengerState==='waiting'&&p.down<=0&&p.panic<=0).sort((a,b)=>distance(activeCar,a)-distance(activeCar,b))[0];if(r&&distance(activeCar,r)<5.5)boardTaxi(r,activeCar);}}
 else if(job.stage==='boarding'){const c=activeCar,r=job.passenger;if(!c||c.type!=='taxi'){r.passengerState='waiting';r.hailing=true;job.stage='seek';job.passenger=null;return;}if(Math.abs(c.speed)>1.3){toast('请停稳，等乘客上车');return;}const door=movePoint(c,c.heading+(r.doorSign||-1)*Math.PI/2,1.40),d=distance(r,door);r.heading=headingTo(r,door);if(d>.32){moveWithCollision(r,r.heading,dt*1.55,.34);animateHuman(r,dt,1.55);}else{animateHuman(r,dt,0);job.boarding+=dt;}if(job.boarding>.7){r.inTaxi=true;r.root.visible=false;r.passengerState='aboard';c.passengerAboard=true;job.taxi=c;const source=nearStreet(c).sample,street=streets[(source.street.id+3)%11],index=(source.index+Math.floor(street.points.length*.37))%(street.points.length-1),dest=streetPoint(street,index,-5.2);if(collides(dest.lat,dest.lon,.5)){const open=findOpenSpot(dest,.5,1);if(open)Object.assign(dest,open);}job.stage='deliver';job.time=0;job.timeLimit=240;job.distance=distance(c,dest);job.fare=Math.round(45+job.distance*.7);setJobGoal(dest);toast('乘客已上车 · 跟随黄色导航到目的地');}}
 else if(job.stage==='deliver'){job.time+=dt;if(job.time>job.timeLimit){job.fare=Math.max(25,job.fare-dt*.12);}if(activeCar===job.taxi&&distance(activeCar,job.goal)<6.0&&Math.abs(activeCar.speed)<1.0)finishTaxi();}}
 else if(job.type==='race'){if(job.stage==='getcar'&&activeCar){job.stage='racing';job.time=0;}if(job.stage==='racing'){job.time+=dt;if(job.time>job.limit){job.stage='failed';setJobGoal(null);toast('计时结束 · 可重新挑战');}else if(activeCar&&distance(activeCar,job.goal)<5.3){job.completed++;if(job.completed>=6){job.stage='complete';raceWins++;cash+=600;setJobGoal(null);toast('计时赛完成 · +$600');audio('reward');saveProgress();}else{setJobGoal(job.checkpoints[job.completed]);audio('switch');}}}}
 else if(job.type==='flight'){if(job.stage==='board'&&activeHeli){job.stage='fly';setJobGoal(job.destination);toast('起飞后飞往黄色标记，降落即可完成投递');}if(job.stage==='fly'&&activeHeli&&distance(activeHeli,job.destination)<4.5&&activeHeli.altitude-job.destination.height<.65&&Math.abs(activeHeli.vertical)<1){job.stage='complete';flightTrips++;cash+=850;setJobGoal(null);toast('直升机投递完成 · +$850');audio('reward');saveProgress();}}
 if(jobMarker&&job.goal){place(jobMarker,job.goal.lat,job.goal.lon,0,job.goal.height+.17);jobMarker.children[1].position.y=2.4+Math.sin(worldTime*3)*.2;jobMarker.children[0].rotation.z=worldTime*.3;}}
function saveProgress(){try{localStorage.setItem('pocket-city-v4',JSON.stringify({schema:1,cash,taxiTrips,raceWins,flightTrips,charId,quality}));}catch(e){}}
function loadProgress(){try{const raw=JSON.parse(localStorage.getItem('pocket-city-v4')||'null');if(!raw||raw.schema!==1)return;cash=clamp(Number(raw.cash)||1992,0,10000000);taxiTrips=clamp(Number(raw.taxiTrips)||0,0,100000);raceWins=clamp(Number(raw.raceWins)||0,0,100000);flightTrips=clamp(Number(raw.flightTrips)||0,0,100000);if([0,1,2].includes(raw.charId)){charId=raw.charId;rebuildPlayer();}updateLabels();}catch(e){}}
function updateAutosave(dt){saveTimer+=dt;if(saveTimer>8){saveTimer=0;saveProgress();}}

function cancelCurrentJob(notify=true){if(!job)return;const r=job.passenger,c=job.taxi||activeCar;if(r){r.inTaxi=false;r.hailing=true;r.passengerState='waiting';r.root.visible=true;r.body.rotation.set(0,0,0);r.hailRing.visible=true;const p=c?findTaxiExit(c):null;if(p){r.lat=p.lat;r.lon=p.lon;}repairActor(r,.29);place(r.root,r.lat,r.lon,r.heading,.08);if(c)c.passengerAboard=false;}job.passenger=null;job.stage=job.type==='taxi'?'seek':'cancelled';job.time=0;setJobGoal(job.type==='taxi'?taxiRiders.find(p=>p.passengerState==='waiting')||null:null);if(notify)toast('当前任务已取消，可重新选择活动');}

