 window.__POCKET_CITY__={version:'0.6.0',get state(){return {started,menuOpen,city:cityId,character:charId,weapon,ammo:ammo[weapon],inCar:!!activeCar,car:activeCar?{type:activeCar.type,speed:activeCar.speed,health:activeCar.health}:null,player:{lat:player.lat,lon:player.lon,heading:player.heading,position:player.root.position.toArray(),speed:player.speed,jumpHeight},cash,health,wanted,missionStage,driveDistance,targetHits,stolenCount,orbit,cars:cars.length,pedestrians:peds.length,buildings:buildings.length,targets:targets.length,nearestCar:nearestCar?{occupied:nearestCar.occupied,distance:distance(player,nearestCar)}:null,aimTarget:aimTarget?.kind||null,renderer:renderer.info.render,frame:frameCounter};}};
